     1→import { createHash, timingSafeEqual } from 'crypto';
     2→import { createJob } from '../lib/tools/create-job.js';
     3→import { setWebhook } from '../lib/tools/telegram.js';
     4→import { githubApi, getJobStatus, fetchJobLog } from '../lib/tools/github.js';
     5→import { getTelegramAdapter } from '../lib/channels/index.js';
     6→import { chat, summarizeJob } from '../lib/ai/index.js';
     7→import { createNotification } from '../lib/db/notifications.js';
     8→import { loadTriggers } from '../lib/triggers.js';
     9→import { verifyApiKey } from '../lib/db/api-keys.js';
    10→import { getConfig } from '../lib/config.js';
    11→
    12→// Bot token — resolved from DB/env, can be overridden by /telegram/register
    13→let telegramBotToken = null;
    14→
    15→// Cached trigger firing function (initialized on first request)
    16→let _fireTriggers = null;
    17→
    18→function getTelegramBotToken() {
    19→  if (!telegramBotToken) {
    20→    telegramBotToken = getConfig('TELEGRAM_BOT_TOKEN') || null;
    21→  }
    22→  return telegramBotToken;
    23→}
    24→
    25→function getFireTriggers() {
    26→  if (!_fireTriggers) {
    27→    const result = loadTriggers();
    28→    _fireTriggers = result.fireTriggers;
    29→  }
    30→  return _fireTriggers;
    31→}
    32→
    33→// Routes that have their own authentication
    34→const PUBLIC_ROUTES = ['/telegram/webhook', '/github/webhook', '/vault-sync', '/ping'];
    35→
    36→/**
    37→ * Timing-safe string comparison.
    38→ * @param {string} a
    39→ * @param {string} b
    40→ * @returns {boolean}
    41→ */
    42→function safeCompare(a, b) {
    43→  if (!a || !b) return false;
    44→  const bufA = Buffer.from(a);
    45→  const bufB = Buffer.from(b);
    46→  if (bufA.length !== bufB.length) return false;
    47→  return timingSafeEqual(bufA, bufB);
    48→}
    49→
    50→/**
    51→ * Centralized auth gate for all API routes.
    52→ * Public routes pass through; everything else requires a valid API key from the database.
    53→ * @param {string} routePath - The route path
    54→ * @param {Request} request - The incoming request
    55→ * @returns {Response|null} - Error response or null if authorized
    56→ */
    57→function checkAuth(routePath, request) {
    58→  if (PUBLIC_ROUTES.includes(routePath)) return null;
    59→
    60→  const apiKey = request.headers.get('x-api-key');
    61→  if (!apiKey) {
    62→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
    63→  }
    64→
    65→  const record = verifyApiKey(apiKey);
    66→  if (!record) {
    67→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
    68→  }
    69→
    70→  return null;
    71→}
    72→
    73→/**
    74→ * Extract job ID from branch name (e.g., "job/abc123" -> "abc123")
    75→ */
    76→function extractJobId(branchName) {
    77→  if (!branchName || !branchName.startsWith('job/')) return null;
    78→  return branchName.slice(4);
    79→}
    80→
    81→// ─────────────────────────────────────────────────────────────────────────────
    82→// Route handlers
    83→// ─────────────────────────────────────────────────────────────────────────────
    84→
    85→async function handleWebhook(request) {
    86→  const body = await request.json();
    87→  const { job } = body;
    88→  if (!job) return Response.json({ error: 'Missing job field' }, { status: 400 });
    89→
    90→  try {
    91→    const result = await createJob(job);
    92→    return Response.json(result);
    93→  } catch (err) {
    94→    console.error(err);
    95→    return Response.json({ error: 'Failed to create job' }, { status: 500 });
    96→  }
    97→}
    98→
    99→async function handleTelegramRegister(request) {
   100→  const body = await request.json();
   101→  const { bot_token, webhook_url } = body;
   102→  if (!bot_token || !webhook_url) {
   103→    return Response.json({ error: 'Missing bot_token or webhook_url' }, { status: 400 });
   104→  }
   105→
   106→  try {
   107→    const result = await setWebhook(bot_token, webhook_url, getConfig('TELEGRAM_WEBHOOK_SECRET'));
   108→    telegramBotToken = bot_token;
   109→    return Response.json({ success: true, result });
   110→  } catch (err) {
   111→    console.error(err);
   112→    return Response.json({ error: 'Failed to register webhook' }, { status: 500 });
   113→  }
   114→}
   115→
   116→async function handleTelegramWebhook(request) {
   117→  const botToken = getTelegramBotToken();
   118→  if (!botToken) return Response.json({ ok: true });
   119→
   120→  const adapter = getTelegramAdapter(botToken);
   121→  const normalized = await adapter.receive(request);
   122→  if (!normalized) return Response.json({ ok: true });
   123→
   124→  // Process message asynchronously (don't block the webhook response)
   125→  processChannelMessage(adapter, normalized).catch((err) => {
   126→    console.error('Failed to process message:', err);
   127→  });
   128→
   129→  return Response.json({ ok: true });
   130→}
   131→
