import { auth } from 'thepopebot/auth';
import { redirect } from 'next/navigation';
import { getPicklistWithOrders } from 'thepopebot/picklist/db';
import { renderPicklistHtml } from 'thepopebot/picklist/print';
import { headers } from 'next/headers';

export default async function PicklistPrintPage({ params }) {
  const session = await auth();
  if (!session?.user) redirect('/login');

  const { id } = await params;
  const data = getPicklistWithOrders(id);
  if (!data) {
    return (
      <div style={{ padding: 32, fontFamily: 'system-ui' }}>
        <h1>Picklist not found</h1>
        <p>The picklist ID <code>{id}</code> does not exist.</p>
      </div>
    );
  }

  const headersList = await headers();
  const host = headersList.get('host') || 'localhost';
  const proto = process.env.NODE_ENV === 'production' ? 'https' : 'http';
  const baseUrl = `${proto}://${host}`;

  const html = renderPicklistHtml(data, baseUrl);

  return (
    <html lang="en">
      <head />
      <body dangerouslySetInnerHTML={{ __html: '' }} />
    </html>
  );
}

// Serve as raw HTML response
export async function generateStaticParams() {
  return [];
}

